const raw = $input.first().json.content || $input.first().json.text;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { category: 'Other', urgency: 'Normal', draft_reply: '' };
}
return [{ json: { ...$input.first().json, ...parsed } }];

